gcYH(){return"\u06a9\u062f \u0645\u0644\u06cc \u0628\u0627\u06cc\u062f \u06f1\u06f0 \u0631\u0642\u0645 \u0628\u0627\u0634\u062f"},
gcYF(){return"\u0634\u0646\u0627\u0633\u0647 \u0645\u0644\u06cc \u0628\u0627\u06cc\u062f \u06f1\u06f1 \u0631\u0642\u0645 \u0628\u0627\u0634\u062f"},
gcYI(){return"\u0646\u0627\u0645 \u0648 \u0646\u0627\u0645 \u062e\u0627\u0646\u0648\u0627\u062f\u06af\u06cc"},
gcYw(){return"\u0646\u0627\u0645 \u0641\u0627\u0631\u0633\u06cc \u0634\u0631\u06a9\u062a"},
gcXa(){return"CSR \u0633\u0627\u062e\u062a\u0647 \u0646\u0634\u062f. \u0646\u0648\u0639 \u0645\u0648\u062f\u06cc \u0648 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0647\u0648\u06cc\u062a\u06cc \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0646\u06cc\u062f."},
gcX9(){return"\u067e\u0633 \u0627\u0632 \u062a\u0648\u0644\u06cc\u062f\u060c CSR \u0631\u0627 \u062f\u0631 \u0645\u0631\u06a9\u0632 \u0635\u062f\u0648\u0631 \u06af\u0648\u0627\u0647\u06cc \u062b\u0628\u062a \u06a9\u0646\u06cc\u062f \u0648 \u0641\u0627\u06cc\u0644 \u06af\u0648\u0627\u0647\u06cc \u0631\u0627 \u062f\u0631 \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u0646\u0645\u0627\u06cc\u06cc\u062f."},
gcYv(){return"\u0646\u0627\u0645 \u0627\u0646\u06af\u0644\u06cc\u0633\u06cc \u0634\u0631\u06a9\u062a"},
